@startuml

class Customer {
  + name
  + surname
  + age
  + address
  + profession
}

class Subscription {
  + type
}

class MonthlySubscription extends Subscription {}

class AnnualSubscription extends Subscription {}

class Service {
  + name
}

class WeightRoom extends Service {}

class SwimmingPool extends Service {}

class ClimbingWall extends Service {}

class Sauna extends Service {}

class TurkishBath extends Service {}

class AdditionalService extends Service {}

class WorkoutPlan {
  + exercises
  + repetitions
  + frequency
  + visitsPerWeek
}

class MedicalStaff {
  + assistCustomer()
  + determineFitnessLevel()
  + defineDiet()
}

class MedicalCheck {
  + weight
  + bodyFat
  + electrocardiogram
  + restingHeartbeat
  + stressHeartbeat
}

class Gym {
  + computeMonthlyBalance()
  + computeYearlyBalance()
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Customer "1" -- "1" Subscription : has
Customer "1" -- "*" Service : requests
Customer "1" -- "0..1" WorkoutPlan : associatedWith
Customer "1" -- "0..1" MedicalStaff : assistedBy
Customer "1" -- "*" MedicalCheck : undergoes
MedicalCheck "*" -- "1" MedicalStaff : performedBy
Gym "1" -- "*" Customer : manages
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" Service : offers

@enduml

